@@ -431,6 +431,27 @@ export const extendTransform = (expression: string): { code: string } | undefine
 			},
 		});

+		// recast drops the parentheses around an `&&` or `||` operand of `??`
+		// when it reprints the node, and mixing them unparenthesized is a
+		// SyntaxError. Make those parentheses explicit so they survive.
+		visit(ast, {
+			visitLogicalExpression(path) {
+				this.traverse(path);
+
+				if (path.node.operator !== '??') return;
+
+				for (const side of ['left', 'right'] as const) {
+					const operand = path.node[side];
+					if (
+						operand.type === 'LogicalExpression' &&
+						(operand.operator === '&&' || operand.operator === '||')
+					) {
+						path.node[side] = types.builders.parenthesizedExpression(operand);
+					}
+				}
+			},
+		});
+
 		return print(ast);
 	} catch (e) {
 		return;
