+		test('Keeps parentheses around && and || operands of ?? when reprinting', () => {
+			const cases = [
+				'($json.a?.b || $json.c) ?? "x".toUpperCase()',
+				'($json.a?.b && $json.c) ?? "x".toUpperCase()',
+				'"x".toUpperCase() ?? ($json.a?.b || $json.c)',
+				'"x".toUpperCase() ?? ($json.a?.b && $json.c)',
+				'$json.a?.b ?? ($json.c || "x".toUpperCase())',
+			];
+			for (const expression of cases) {
+				const code = extendTransform(expression)?.code;
+				expect(code).toBeDefined();
+				// Mixing ?? with an unparenthesized && or || is a SyntaxError
+				expect(() => parseScript(code!)).not.toThrow();
+			}
+
+			expect(evaluate('={{ ({}?.a || false) ?? "x".toUpperCase() }}')).toBe(false);
+			expect(evaluate('={{ (null || null) ?? "x".toUpperCase() }}')).toBe('X');
+			expect(evaluate('={{ "x".toUpperCase() ?? ({}?.a && 1) }}')).toBe('X');
+		});
+
 		test('Optional chaining with undefined argument', () => {
 			expect(evaluate('={{ [1, 2, 3, 4]?.sum((undefined)?.test) }}')).toBe(10);
 		});
